window.OSHA_QUESTIONS = [
  { id: "in-01", category: "intro", topic: "OSH Act", q: "The Occupational Safety and Health Act that created OSHA was passed in:", choices: ["1960", "1970", "1986", "2001"], a: 1, why: "Congress passed the OSH Act in 1970. OSHA opened in 1971 under the U.S. Department of Labor." },
  { id: "in-02", category: "intro", topic: "Agency", q: "OSHA is an agency of which federal department?", choices: ["Department of Commerce", "Department of Transportation", "Department of Labor", "Department of Homeland Security"], a: 2, why: "OSHA is part of the U.S. Department of Labor. The Assistant Secretary of Labor for OSHA heads the agency." },
  { id: "in-03", category: "intro", topic: "General Duty Clause", q: "Section 5(a)(1) of the OSH Act — the General Duty Clause — requires employers to:", choices: ["Pay overtime for all safety meetings", "Furnish a workplace free from recognized hazards that are causing or likely to cause death or serious physical harm", "Provide OSHA 30 cards to every new hire within 24 hours", "Inspect every tool daily with a written checklist even when unused"], a: 1, why: "When no specific standard applies, the General Duty Clause still requires employers to address serious recognized hazards." },
  { id: "in-04", category: "intro", topic: "Worker rights", q: "Which of the following is a worker right under OSHA?", choices: ["The right to a safe workplace and to raise safety concerns without retaliation", "The right to skip required training if busy", "The right to refuse all PPE", "The right to keep injuries off the OSHA log by request"], a: 0, why: "Workers may file complaints, participate in inspections, receive training, and be protected from retaliation under Section 11(c)." },
  { id: "in-05", category: "intro", topic: "Complaints", q: "A worker who believes there is a serious hazard can:", choices: ["Only tell a coworker", "File a confidential complaint with OSHA", "Wait until an injury occurs", "Call the fire department instead of OSHA in every case"], a: 1, why: "Anyone can file an OSHA complaint. Workers may request that their name be kept confidential from the employer." },
  { id: "in-06", category: "intro", topic: "Fatality reporting", q: "Employers must report a work-related fatality to OSHA within:", choices: ["1 hour", "8 hours", "24 hours", "7 days"], a: 1, why: "29 CFR 1904.39: report fatalities within 8 hours of learning about them." },
  { id: "in-07", category: "intro", topic: "Severe injury reporting", q: "In-patient hospitalization, amputation, or loss of an eye must be reported to OSHA within:", choices: ["8 hours", "24 hours", "7 days", "30 days"], a: 1, why: "These severe injuries must be reported within 24 hours. Fatalities remain on the 8-hour clock." },
  { id: "in-08", category: "intro", topic: "300A posting", q: "The OSHA 300A annual summary must be posted from:", choices: ["January 1 through January 31", "February 1 through April 30", "July 1 through September 30", "Only on the day of an inspection"], a: 1, why: "Covered employers post the 300A in a conspicuous place from February 1 to April 30." },
  { id: "in-09", category: "intro", topic: "Inspection priority", q: "Which inspection type has the highest OSHA priority?", choices: ["Programmed planned inspections", "Employee complaints", "Imminent danger", "Follow-up inspections"], a: 2, why: "Priority order is generally imminent danger, then fatality/catastrophe, complaints/referrals, then programmed inspections." },
  { id: "in-10", category: "intro", topic: "Citations", q: "How long does an employer generally have to contest an OSHA citation?", choices: ["7 calendar days", "15 working days", "30 calendar days", "90 days"], a: 1, why: "Employers have 15 working days from receipt of a citation to file a Notice of Contest." },
  { id: "in-11", category: "intro", topic: "Whistleblower", q: "Section 11(c) of the OSH Act protects workers who:", choices: ["Ignore lockout procedures", "Suffer retaliation for raising safety concerns or participating in OSHA activities", "Refuse to wear required hearing protection", "Alter injury records at the supervisor’s request"], a: 1, why: "It is illegal to fire, demote, or otherwise retaliate against a worker for protected safety activity." },
  { id: "in-12", category: "intro", topic: "Training", q: "Who is responsible for providing required OSHA safety training to workers?", choices: ["OSHA inspectors during every visit", "The employer", "The worker’s union only", "The equipment manufacturer only"], a: 1, why: "Employers must train workers on hazards and required protections in a language and vocabulary they understand." },
  { id: "in-13", category: "intro", topic: "State plans", q: "A state OSHA plan must be:", choices: ["Weaker than federal OSHA so businesses can compete", "At least as effective as federal OSHA", "Limited to construction only", "Optional for public employees only in every state"], a: 1, why: "State Plans covering private-sector workers must be at least as effective as federal OSHA and may be stricter." },
  { id: "in-14", category: "intro", topic: "Outreach cards", q: "An OSHA 10 or 30 Outreach card:", choices: ["Is a federal license to supervise any jobsite", "Is issued only after completing the required hours with an authorized trainer — it is not a substitute for the official course", "Expires 30 days after the test", "Lets you skip fall protection on residential work"], a: 1, why: "Outreach is awareness training. Only authorized trainers issue DOL cards after the course hours. Practice quizzes do not issue a card." },
  { id: "in-15", category: "intro", topic: "Recordkeeping", q: "OSHA Form 300 is used to:", choices: ["Apply for a variance", "Log work-related injuries and illnesses", "Report a fatality by phone", "Certify crane operators"], a: 1, why: "Form 300 is the log. Form 301 is the incident report. Form 300A is the annual summary." },

  { id: "ff-01", category: "focusFour", topic: "The four", q: "OSHA’s construction “Focus Four” hazards are:", choices: ["Noise, heat, silica, and lead", "Falls, struck-by, caught-in/between, and electrocution", "Fire, confined space, LOTO, and forklifts", "Asbestos, radiation, lasers, and vibration"], a: 1, why: "These four cause the majority of construction fatalities. Outreach courses emphasize them heavily." },
  { id: "ff-02", category: "focusFour", topic: "Leading killer", q: "Which Focus Four hazard is the leading cause of death in construction?", choices: ["Electrocution", "Caught-in/between", "Falls", "Struck-by"], a: 2, why: "Falls from height consistently account for the largest share of construction fatalities." },
  { id: "ff-03", category: "focusFour", topic: "Struck-by", q: "Struck-by hazards include being hit by:", choices: ["Only hand tools dropped from 6 feet or more", "Flying, falling, swinging, or rolling objects", "Only vehicles over 26,001 pounds", "Only objects heavier than 50 pounds"], a: 1, why: "Cranes, vehicles, masonry, powder-actuated tools, and falling materials are common struck-by sources." },
  { id: "ff-04", category: "focusFour", topic: "Caught-in", q: "A classic caught-in/between fatality is:", choices: ["A trench wall collapse burying a worker", "A sunburn", "Hearing loss over 20 years", "A paper cut"], a: 0, why: "Trench collapses, unguarded machinery, and collapsing structures are caught-in/between events." },
  { id: "ff-05", category: "focusFour", topic: "Electrocution", q: "Electrocution on construction sites most often involves:", choices: ["Contact with overhead power lines or damaged cords and tools", "Only lightning", "Only 12-volt vehicle batteries", "Static from plastic pipe"], a: 0, why: "Cranes, ladders, and siding near overhead lines, plus defective cords and missing GFCI, cause many deaths." },
  { id: "ff-06", category: "focusFour", topic: "Prevention", q: "The most effective way to control a Focus Four hazard is usually to:", choices: ["Rely on PPE alone", "Eliminate or engineer the hazard out (for example, guardrails instead of hoping workers remember a harness)", "Post a poster and do nothing else", "Wait until after an incident"], a: 1, why: "Hierarchy of controls: elimination and engineering beat PPE. Guardrails beat a harness that may not be tied off." },
  { id: "ff-07", category: "focusFour", topic: "Hard hats", q: "Hard hats help primarily against which Focus Four hazard?", choices: ["Caught-in trench collapse", "Struck-by from falling or flying objects", "Electrocution from overhead lines in every case", "Falls from a roof edge"], a: 1, why: "Hard hats (and staying out of the drop zone) reduce struck-by head injuries. They are not fall protection." },

  { id: "fp-01", category: "fallProtection", topic: "Construction trigger", q: "In construction, fall protection is generally required when walking/working surfaces are how far above a lower level?", choices: ["4 feet", "6 feet", "10 feet", "15 feet"], a: 1, why: "29 CFR 1926.501: 6 feet is the general construction trigger. Scaffolds, steel erection, and a few other activities have different heights." },
  { id: "fp-02", category: "fallProtection", topic: "General industry", q: "In general industry, fall protection is generally required at:", choices: ["4 feet", "6 feet", "10 feet", "Only at 15 feet"], a: 0, why: "29 CFR 1910.28 generally uses 4 feet for unprotected sides and edges." },
  { id: "fp-03", category: "fallProtection", topic: "Conventional systems", q: "The three conventional fall-protection systems are:", choices: ["Hard hats, gloves, and boots", "Guardrails, safety nets, and personal fall arrest systems", "Warning tape, cones, and a spotter only", "Ladders, ramps, and stairs"], a: 1, why: "1926.501/502 identify guardrail systems, safety net systems, and personal fall arrest as conventional protection." },
  { id: "fp-04", category: "fallProtection", topic: "Top rail", q: "A construction guardrail top rail must be about how high?", choices: ["21 inches ± 3 inches", "42 inches ± 3 inches (39 to 45 inches)", "60 inches exactly", "12 inches"], a: 1, why: "1926.502(b): top edge 42 inches plus or minus 3 inches above the walking/working surface." },
  { id: "fp-05", category: "fallProtection", topic: "Top rail strength", q: "A guardrail top rail must withstand a force of at least:", choices: ["50 pounds", "100 pounds", "200 pounds", "5,000 pounds"], a: 2, why: "Top rails: 200 lb in the outward/downward direction. Midrails: 150 lb. Toeboards: 50 lb." },
  { id: "fp-06", category: "fallProtection", topic: "Anchorage", q: "A personal fall-arrest anchorage must be capable of supporting at least:", choices: ["250 pounds", "1,000 pounds", "5,000 pounds per employee attached, or be designed by a qualified person with a safety factor of at least two", "The worker’s body weight only"], a: 2, why: "1926.502(d)(15): 5,000 lb per employee, or a qualified-person design with a factor of at least two." },
  { id: "fp-07", category: "fallProtection", topic: "Free fall", q: "Personal fall arrest generally must limit free fall to:", choices: ["2 feet", "6 feet", "12 feet", "30 feet"], a: 1, why: "Free fall is limited to 6 feet, and the system must prevent contact with a lower level." },
  { id: "fp-08", category: "fallProtection", topic: "Safety nets", q: "Safety nets must be installed as close as practicable under the working surface, but not more than:", choices: ["6 feet below", "10 feet below", "30 feet below", "50 feet below"], a: 2, why: "1926.502(c)(1): nets no more than 30 feet below. Closer is better." },
  { id: "fp-09", category: "fallProtection", topic: "Hole covers", q: "Hole covers must be:", choices: ["Any piece of cardboard", "Secured, marked “HOLE” or “COVER” or similar, and able to support at least twice the intended load", "Painted yellow only, with no strength requirement", "Optional if the hole is smaller than 12 inches"], a: 1, why: "1926.502(i): color-code or mark covers, secure them, and design for at least twice the load of employees, equipment, and materials." },
  { id: "fp-10", category: "fallProtection", topic: "Scaffolds", q: "On scaffolds, fall protection is generally required at:", choices: ["4 feet", "6 feet", "10 feet", "15 feet"], a: 2, why: "1926.451(g): 10 feet above a lower level for scaffold work (with some exceptions such as pump jacks)." },
  { id: "fp-11", category: "fallProtection", topic: "Steel erection", q: "Under Subpart R, fall protection for steel erection is generally required at:", choices: ["6 feet for all connectors", "15 feet (connectors have limited additional rules)", "30 feet", "Only at 25 feet"], a: 1, why: "1926.760: 15-foot general trigger. Connectors have specific provisions between 15 and 30 feet." },
  { id: "fp-12", category: "fallProtection", topic: "PFAS parts", q: "A personal fall arrest system typically includes:", choices: ["Hard hat, glasses, and gloves", "Anchorage, connecting device (lanyard or lifeline/SRL), and full-body harness", "A body belt and a rope around a pipe", "A warning line only"], a: 1, why: "ABC: Anchorage, Body harness, Connecting device. Body belts are not allowed for fall arrest." },
  { id: "fp-13", category: "fallProtection", topic: "Body belts", q: "Body belts may be used for:", choices: ["Fall arrest in construction", "Positioning or travel restraint, but not as a fall-arrest harness", "Ladder climbing only", "Any fall over 6 feet"], a: 1, why: "OSHA prohibited body belts for personal fall arrest because they can cause severe abdominal injury. Use a full-body harness." },
  { id: "fp-14", category: "fallProtection", topic: "Warning line", q: "On a low-slope roof, a warning line used instead of conventional protection during roofing generally must be at least how far from the edge when mechanical equipment is not used?", choices: ["3 feet", "6 feet", "15 feet", "25 feet"], a: 1, why: "1926.502(f): 6 feet from the roof edge without mechanical equipment; 10 feet on sides perpendicular to equipment travel when equipment is used." },
  { id: "fp-15", category: "fallProtection", topic: "Toeboards", q: "Toeboards on guardrail systems are generally at least:", choices: ["1 inch high", "3.5 inches high", "12 inches high", "42 inches high"], a: 1, why: "1926.502(j): toeboards at least 3.5 inches, no more than 1/4-inch clearance above the surface, 50 lb strength." },
  { id: "fp-16", category: "fallProtection", topic: "Inspection", q: "Personal fall arrest equipment must be inspected:", choices: ["Once a year only", "Before each use", "Only after a fall", "Only by OSHA"], a: 1, why: "1926.502(d)(21): inspect PFAS before each use. Equipment that arrested a fall is removed from service." },

  { id: "ld-01", category: "ladders", topic: "4:1", q: "Portable ladders used to access an upper level should be set at about a:", choices: ["1:1 ratio (45 degrees)", "4:1 ratio — 1 foot out for every 4 feet of working length", "8:1 ratio", "Vertical 90-degree lean against the wall"], a: 1, why: "1926.1053(b)(5)(i): about 75 degrees, or 1:4. A common check is stand with toes at the base and arms out — the rails should be near your hands." },
  { id: "ld-02", category: "ladders", topic: "Extension", q: "When a portable ladder is used to access an upper landing, side rails must extend at least:", choices: ["1 foot above the landing", "3 feet above the landing", "6 feet above the landing", "Flush with the landing"], a: 1, why: "1926.1053(b)(1): at least 3 feet above the upper landing, or the ladder must be secured and a grab device provided." },
  { id: "ld-03", category: "ladders", topic: "Three-point", q: "Three-point contact on a ladder means:", choices: ["Three people on the ladder", "Two hands and one foot, or two feet and one hand, in contact while climbing", "Three rungs skipped at a time", "The ladder touching the wall at three points"], a: 1, why: "Keep control while climbing. Do not carry loads that prevent a handhold." },
  { id: "ld-04", category: "ladders", topic: "Stepladder", q: "On a stepladder you should not:", choices: ["Face the ladder", "Stand on the top cap or the top step (unless the manufacturer designed that step for standing)", "Lock the spreaders", "Place it on firm level ground"], a: 1, why: "The top cap is not a step. Overreaching and standing too high are common fall causes." },
  { id: "ld-05", category: "ladders", topic: "Metal ladders", q: "Metal ladders should not be used:", choices: ["Outdoors", "Where they can contact energized electrical equipment", "On concrete", "If they have non-slip feet"], a: 1, why: "Metal conducts electricity. Use fiberglass near electrical work and maintain clearance from lines." },
  { id: "ld-06", category: "ladders", topic: "Inspect", q: "Ladders must be inspected:", choices: ["Only when purchased", "For visible defects before use, and after any incident that could affect strength", "Every five years", "Only by a professional engineer"], a: 1, why: "1926.1053(b)(15): a competent person inspects periodically; users look for defects before each use." },
  { id: "ld-07", category: "ladders", topic: "Scaffold inspection", q: "Scaffolds must be inspected by a competent person:", choices: ["Once per project", "Before each work shift and after any occurrence that could affect structural integrity", "Only after a collapse", "Monthly"], a: 1, why: "1926.451(f)(3): competent person inspects before each shift and after events such as weather that could affect the scaffold." },
  { id: "ld-08", category: "ladders", topic: "Scaffold PF", q: "Each employee on a scaffold more than 10 feet above a lower level must be protected by:", choices: ["A hard hat only", "Guardrails and/or a personal fall arrest system as required for that scaffold type", "A warning line only", "Nothing if they have 3 years of experience"], a: 1, why: "1926.451(g) sets scaffold fall-protection rules. Many supported scaffolds use guardrails; some require PFAS." },
  { id: "ld-09", category: "ladders", topic: "Planking", q: "Scaffold platforms must be:", choices: ["Planked with random lumber of any grade", "Fully planked or decked between the front uprights and the guardrail supports", "Left with 18-inch gaps for tool access", "Only one plank wide at any height"], a: 1, why: "1926.451(b): fully planked, scaffold-grade planks, openings generally not more than 1 inch unless more is necessary." },
  { id: "ld-10", category: "ladders", topic: "Width", q: "Each scaffold platform and walkway must be at least how wide (with limited exceptions)?", choices: ["8 inches", "12 inches", "18 inches", "36 inches"], a: 2, why: "1926.451(b)(2): at least 18 inches wide. Ladder-jack, top-plate bracket, roof-bracket, and pump-jack scaffolds have specific exceptions." },
  { id: "ld-11", category: "ladders", topic: "Ties", q: "Supported scaffolds with a height-to-base ratio of more than 4:1 must be:", choices: ["Painted orange", "Restrained by guys, ties, or braces to prevent tipping", "Used only indoors", "Limited to one worker"], a: 1, why: "1926.451(c)(1): restrain scaffolds that would otherwise be unstable. Ties typically start at the 4:1 height." },
  { id: "ld-12", category: "ladders", topic: "Load", q: "Scaffolds and their components must be capable of supporting:", choices: ["The weight of one worker only", "Their own weight plus at least 4 times the maximum intended load", "Twice the intended load", "Any load the crew decides to place"], a: 1, why: "1926.451(a)(1): 4:1 safety factor on the maximum intended load, not including the scaffold’s own weight in that multiplier." },

  { id: "ex-01", category: "excavation", topic: "5-foot rule", q: "A protective system is generally required in excavations:", choices: ["Deeper than 2 feet", "5 feet or deeper, unless the excavation is in stable rock or a competent person finds no cave-in potential", "Only at 20 feet", "Never if workers wear hard hats"], a: 1, why: "1926.652(a): 5 feet is the usual trigger. Less than 5 feet still needs protection if a competent person sees cave-in danger." },
  { id: "ex-02", category: "excavation", topic: "Competent person", q: "Who must inspect excavations daily?", choices: ["Any laborer", "A competent person", "OSHA only", "The equipment dealer"], a: 1, why: "1926.651(k): a competent person inspects daily, throughout the shift as needed, and after rain or other hazard-increasing events." },
  { id: "ex-03", category: "excavation", topic: "Spoil", q: "Spoil piles and other materials must be kept at least how far from the edge of an excavation?", choices: ["6 inches", "2 feet", "6 feet", "10 feet"], a: 1, why: "1926.651(j)(2): keep spoil, tools, and equipment at least 2 feet from the edge, or use retaining devices." },
  { id: "ex-04", category: "excavation", topic: "Egress", q: "In trenches 4 feet or deeper, a stairway, ladder, ramp, or other means of egress must be within:", choices: ["10 feet of lateral travel", "25 feet of lateral travel", "50 feet of lateral travel", "100 feet of lateral travel"], a: 1, why: "1926.651(c)(2): 25 feet of lateral travel to egress in trenches 4 feet or more in depth." },
  { id: "ex-05", category: "excavation", topic: "Type C", q: "Type C soil — the least stable in OSHA’s excavation tables — is generally sloped no steeper than:", choices: ["1/2 : 1 (63 degrees)", "3/4 : 1 (53 degrees)", "1 : 1 (45 degrees)", "1.5 : 1 (34 degrees)"], a: 3, why: "Appendix B: Type A 3/4:1, Type B 1:1, Type C 1½:1 for simple slope excavations under 20 feet." },
  { id: "ex-06", category: "excavation", topic: "20 feet", q: "Protective systems for excavations 20 feet or deeper must be:", choices: ["The same as a 6-foot trench", "Designed by a registered professional engineer", "Skipped if soil looks dry", "Limited to sloping only with no design"], a: 1, why: "1926.652(b) and (c): at 20 feet and deeper, sloping, benching, shielding, or shoring must be PE-designed or follow tabulated data accordingly." },
  { id: "ex-07", category: "excavation", topic: "Utilities", q: "Before opening an excavation, the employer must:", choices: ["Guess where utilities are", "Determine the location of underground utilities and contact the utility locator / 811 as required", "Only look for overhead lines", "Dig at night so traffic is lighter"], a: 1, why: "1926.651(b): determine underground installations. Call 811 / the one-call system before you dig." },
  { id: "ex-08", category: "excavation", topic: "Water", q: "Water accumulating in an excavation:", choices: ["Stabilizes the soil", "Increases cave-in and drowning hazards and generally requires controls and a competent person’s evaluation", "Means Type A soil", "Is only a problem below 20 feet"], a: 1, why: "1926.651(h): employees cannot work in excavations where water is accumulating unless precautions are in place." },
  { id: "ex-09", category: "excavation", topic: "Atmosphere", q: "Where oxygen deficiency or a hazardous atmosphere could reasonably exist (for example, excavations in landfill or near tanks), testing is required when the depth is greater than:", choices: ["2 feet", "4 feet", "8 feet", "20 feet"], a: 1, why: "1926.651(g): test before employees enter excavations greater than 4 feet if a hazardous atmosphere could exist." },
  { id: "ex-10", category: "excavation", topic: "Unprotected", q: "If a trench is deeper than 5 feet and has no protective system, workers should:", choices: ["Work quickly so exposure is short", "Not enter until a proper system is in place", "Lie down to stay below the spoil pile", "Use a wooden pallet as a shield"], a: 1, why: "Cave-ins kill in seconds. There is no “work fast” exception. Slope, shore, or shield first." },

  { id: "el-01", category: "electrical", topic: "Overhead clearance", q: "Unless the line is de-energized and grounded, keep unqualified workers and conductive objects at least how far from overhead power lines up to 50 kV?", choices: ["3 feet", "6 feet", "10 feet", "20 feet"], a: 2, why: "1910.333 and 1926.416: 10 feet for lines 50 kV or less. Greater voltages need more distance." },
  { id: "el-02", category: "electrical", topic: "GFCI", q: "On construction sites, 120-volt, 15- and 20-amp temporary receptacles generally must have:", choices: ["A GFCI or an assured equipment grounding conductor program", "Only a two-prong adapter", "A 30-amp breaker", "No protection if indoors"], a: 0, why: "1926.404(b)(1): GFCI protection or a documented AEGCP. GFCI is the usual choice." },
  { id: "el-03", category: "electrical", topic: "Qualified person", q: "Work on energized electrical parts generally may be done only by:", choices: ["Any helper with rubber boots", "A qualified person using required safe work practices", "Anyone with an OSHA 10 card", "The site superintendent only"], a: 1, why: "1910.333 / 1926 Subpart K: only qualified persons work on or near exposed live parts, and de-energizing is preferred." },
  { id: "el-04", category: "electrical", topic: "Cords", q: "Flexible cords with damaged insulation or missing ground pins should be:", choices: ["Wrapped with electrical tape and kept in service", "Removed from service until repaired by a qualified person or replaced", "Used only in dry weather", "Used only under 50 volts"], a: 1, why: "Damaged cords are a leading electrocution and shock source. Do not “tape and hope.”" },
  { id: "el-05", category: "electrical", topic: "50 volts", q: "Live parts of electrical equipment operating at 50 volts or more must be:", choices: ["Painted red", "Guarded against accidental contact", "Accessible to everyone for reset", "Sprayed with water if they arc"], a: 1, why: "1910.303 / 1926.403: guard live parts 50 volts or more by location or enclosures." },
  { id: "el-06", category: "electrical", topic: "Cranes vs lines", q: "Unless voltage is confirmed and Table A clearances are used, crane operations must keep a minimum approach of:", choices: ["4 feet", "10 feet", "20 feet from overhead power lines", "50 feet"], a: 2, why: "1926.1408: 20-foot encroachment prevention for lines up to 350 kV when voltage is unknown, or use Table A if voltage is known." },
  { id: "el-07", category: "electrical", topic: "Grounding", q: "The equipment grounding conductor in a cord-and-plug tool:", choices: ["Is optional if the tool is double-insulated", "Carries fault current so a breaker or GFCI can clear a ground fault on tools that require a ground", "Increases voltage", "Is only for data cables"], a: 1, why: "Double-insulated tools may use a two-wire cord. Grounded tools need an intact ground path." },
  { id: "el-08", category: "electrical", topic: "Wet conditions", q: "Using electrical tools in wet or damp conditions:", choices: ["Is always forbidden", "Raises shock risk; use GFCI, proper PPE, and keep cords and tools in good condition", "Is safer because water grounds the circuit", "Only matters above 480 volts"], a: 1, why: "Water lowers resistance. GFCI, dry standing places, and de-energizing reduce the risk." },
  { id: "el-09", category: "electrical", topic: "De-energize", q: "The preferred method before electrical work is:", choices: ["Work live with leather gloves", "De-energize, lock/tag, and verify absence of voltage", "Shut off only the light switch in the room", "Tape over the breaker"], a: 1, why: "1910.333 and LOTO 1910.147: de-energize unless infeasibility or increased hazard can be demonstrated." },
  { id: "el-10", category: "electrical", topic: "Test", q: "After locking out a circuit, before you touch conductors you should:", choices: ["Assume it is dead because the switch is off", "Test for absence of voltage with a known-working tester", "Lick a finger to check for tingle", "Wait 10 seconds"], a: 1, why: "Always verify. Wrong breaker, stored energy, and induced voltage kill people who “knew” it was off." },

  { id: "pp-01", category: "ppe", topic: "Hierarchy", q: "In the hierarchy of controls, PPE is:", choices: ["The first and best control", "The last line of defense after elimination, substitution, engineering, and administrative controls", "Never required if a hard hat is worn", "A substitute for machine guards"], a: 1, why: "PPE fails if it is missing, wrong, or unused. Engineer the hazard out when you can." },
  { id: "pp-02", category: "ppe", topic: "Payment", q: "Employers must pay for most PPE, including:", choices: ["Only hard hats if the worker asks twice", "Hard hats, hearing protection, and most specialty safety glasses and gloves required by the standard", "Everyday clothing such as long pants", "Logging boots in every industry"], a: 1, why: "1910.132(h) / 1926.95: employer pays for required PPE with listed exceptions (non-specialty safety-toe shoes, everyday clothing, un-special prescription eyewear, etc.)." },
  { id: "pp-03", category: "ppe", topic: "Payment exception", q: "Which item is an example of PPE the employer generally does not have to pay for?", choices: ["A welding helmet required for the job", "Non-specialty steel-toe boots that the employee can wear off the jobsite", "A respirator required by OSHA", "Electrical insulating gloves"], a: 1, why: "Employers need not pay for non-specialty safety-toe protective footwear that is not used only at work, among a short list of exceptions." },
  { id: "pp-04", category: "ppe", topic: "Assessment", q: "Before requiring PPE, the employer must:", choices: ["Buy the cheapest glasses", "Assess workplace hazards that require PPE", "Wait for an OSHA inspection", "Let each worker choose any sunglasses"], a: 1, why: "1910.132(d): documented hazard assessment and PPE selection. Construction has parallel duties to provide and require PPE." },
  { id: "pp-05", category: "ppe", topic: "Hard hats", q: "Industrial hard hats are typically certified to:", choices: ["ANSI/ISEA Z89.1", "ANSI Z87.1 only", "NFPA 70E only", "ASTM D4236"], a: 0, why: "Z89.1 covers Type I/II and electrical Classes G, E, and C. Z87.1 is eye and face protection." },
  { id: "pp-06", category: "ppe", topic: "Eye", q: "Safety glasses used for impact protection should meet:", choices: ["ANSI/ISEA Z87.1", "ANSI Z89.1", "Only “CE” fashion markings", "No standard if they look dark"], a: 0, why: "Look for Z87 or Z87+ markings. Side protection is required where flying particles are a hazard." },
  { id: "pp-07", category: "ppe", topic: "Hearing action", q: "OSHA’s noise action level (when a hearing conservation program is generally required in general industry) is an 8-hour TWA of:", choices: ["70 dBA", "85 dBA", "90 dBA", "140 dBA"], a: 1, why: "1910.95: 85 dBA 8-hour TWA is the action level. 90 dBA is the PEL. 140 dB peak is a separate impulsive limit." },
  { id: "pp-08", category: "ppe", topic: "Noise PEL", q: "The OSHA permissible exposure limit for noise is an 8-hour TWA of:", choices: ["80 dBA", "85 dBA", "90 dBA", "100 dBA"], a: 2, why: "90 dBA PEL with a 5 dB exchange rate. Many safety programs still start hearing protection at 85 dBA." },
  { id: "pp-09", category: "ppe", topic: "Respirator medical", q: "Before a worker uses a tight-fitting respirator, the employer must provide:", choices: ["Only a pamphlet", "A medical evaluation", "A chest X-ray in every case", "Nothing if the respirator is an N95"], a: 1, why: "1910.134: medical evaluation before fit testing and use, including for N95s used as respirators (not voluntary use exceptions)." },
  { id: "pp-10", category: "ppe", topic: "Fit test", q: "Tight-fitting respirators require fit testing:", choices: ["Once in a career", "Initially and at least annually, and when facial changes occur", "Only if the worker has a beard", "Never for half-masks"], a: 1, why: "1910.134(f): qualitative or quantitative fit test before first use, annually, and after changes that affect seal." },
  { id: "pp-11", category: "ppe", topic: "Facial hair", q: "A worker who must wear a tight-fitting respirator:", choices: ["May keep a full beard if they use extra straps", "Cannot have facial hair that comes between the sealing surface and the face", "Is exempt if they sign a waiver", "Only needs a hooded PAPR in every case"], a: 1, why: "Hair in the seal causes leakage. Clean-shaven where the respirator seals, or use a loose-fitting hooded respirator if the program allows." },
  { id: "pp-12", category: "ppe", topic: "Gloves", q: "Chemical-resistant gloves should be selected based on:", choices: ["Color only", "The chemical, breakthrough time, and the task", "Whatever is in the gang box", "Cotton for every solvent"], a: 1, why: "SDS Section 8 and manufacturer chemical-resistance charts. Nitrile is not universal." },
  { id: "pp-13", category: "ppe", topic: "High-vis", q: "Workers exposed to public vehicular traffic in construction generally need:", choices: ["No special clothing", "High-visibility warning garments as required by the MUTCD / 1926.201", "Only a hard hat", "Camouflage"], a: 1, why: "1926.201 and the MUTCD require high-visibility apparel in many traffic-control situations." },
  { id: "pp-14", category: "ppe", topic: "Training", q: "PPE training must cover:", choices: ["When PPE is needed, what to use, how to wear it, limitations, and care", "Only the brand name", "How to bill the client", "Nothing if PPE is “common sense”"], a: 0, why: "1910.132(f): train, then retrain if the worker shows they do not understand or if PPE/hazards change." },
  { id: "pp-15", category: "ppe", topic: "Damaged", q: "Damaged or defective PPE must be:", choices: ["Used until the end of the shift", "Taken out of service", "Given to new hires", "Painted to hide cracks"], a: 1, why: "Cracked hard hats, fogged or pitted lenses, and frayed harnesses do not protect. Replace them." },

  { id: "hc-01", category: "hazcom", topic: "Purpose", q: "The Hazard Communication Standard is often called the:", choices: ["Lockout rule", "Right-to-know / worker information standard", "Fall protection standard", "Confined space standard"], a: 1, why: "1910.1200: workers have a right to know the identities and hazards of chemicals they work with." },
  { id: "hc-02", category: "hazcom", topic: "SDS", q: "Safety Data Sheets under GHS have how many sections?", choices: ["8", "12", "16", "24"], a: 2, why: "GHS SDS format is 16 sections. Section 2 is hazards; Section 4 first aid; Section 8 exposure controls/PPE." },
  { id: "hc-03", category: "hazcom", topic: "Signal words", q: "The two GHS signal words are:", choices: ["Caution and Notice", "Danger and Warning", "Stop and Yield", "Fatal and Harmful"], a: 1, why: "Danger is more severe than Warning. Not every chemical uses a signal word." },
  { id: "hc-04", category: "hazcom", topic: "Pictograms", q: "GHS hazard pictograms are:", choices: ["Optional clip art", "Red-bordered diamonds with a black symbol on white", "Blue circles only", "Green squares"], a: 1, why: "OSHA requires the standardized pictograms (skull, flame, corrosion, etc.). The environmental pictogram is not mandatory under OSHA." },
  { id: "hc-05", category: "hazcom", topic: "Secondary labels", q: "A workplace (secondary) container generally must be labeled unless:", choices: ["The worker will use it immediately under their exclusive control and leave no unmarked leftovers", "It holds water only, in every case including acids", "It is a 55-gallon drum", "The chemical is not hazardous"], a: 0, why: "Portable containers for immediate use by the employee who transferred the chemical can be unlabeled. Do not leave unlabeled chemicals for the next shift." },
  { id: "hc-06", category: "hazcom", topic: "Written program", q: "Employers with hazardous chemicals must have:", choices: ["A written HazCom program, chemical inventory, SDS access, labels, and training", "Only SDSs in a locked office", "Verbal warnings only", "No program if they have fewer than 10 employees in every case"], a: 0, why: "1910.1200(e): written program. SDS must be readily accessible on the shift." },
  { id: "hc-07", category: "hazcom", topic: "Training", q: "HazCom training is required:", choices: ["Only for chemists", "Before a worker is assigned to work with hazardous chemicals, and when new hazards are introduced", "Once every 10 years", "Only after a spill"], a: 1, why: "Train on labels, SDS, hazards of chemicals in the work area, and protective measures." },
  { id: "hc-08", category: "hazcom", topic: "Section 2", q: "Which SDS section lists the chemical’s hazards, including signal word and pictograms?", choices: ["Section 1 Identification", "Section 2 Hazard identification", "Section 16 Other information", "Section 14 Transport"], a: 1, why: "Section 2 is the quick hazard snapshot. Still read PPE and first-aid sections before you use the product." },
  { id: "hc-09", category: "hazcom", topic: "Danger vs Warning", q: "On a GHS label, “Danger” means:", choices: ["A less severe hazard than Warning", "A more severe hazard than Warning", "The chemical is banned", "No PPE is needed"], a: 1, why: "Danger is the higher signal word. Warning is used for less severe hazard categories." },
  { id: "hc-10", category: "hazcom", topic: "Inventory", q: "A chemical inventory (list) is required so that:", choices: ["OSHA can bill per chemical", "The employer can match SDSs to what is actually on site", "Workers can skip labels", "Only flammables are tracked"], a: 1, why: "The list is part of the written program and is how you know SDS coverage is complete." },

  { id: "lo-01", category: "loto", topic: "Purpose", q: "The purpose of lockout/tagout is to:", choices: ["Speed up production", "Control hazardous energy during servicing and maintenance so equipment cannot start or release energy", "Replace machine guards permanently", "Train only electricians"], a: 1, why: "1910.147 covers electrical, mechanical, hydraulic, pneumatic, chemical, thermal, and other energy." },
  { id: "lo-02", category: "loto", topic: "Authorized", q: "An authorized employee is someone who:", choices: ["Walks past the machine", "Locks out or tags out machines to perform servicing", "Only reads the procedure", "Owns the company"], a: 1, why: "Authorized employees apply locks/tags. Affected employees operate or work in the area. Other employees need awareness." },
  { id: "lo-03", category: "loto", topic: "Affected", q: "An affected employee must:", choices: ["Remove authorized employees’ locks if production is behind", "Be notified and not attempt to start locked-out equipment", "Perform the lockout without training", "Bypass the lock with a spare key"], a: 1, why: "Affected employees are told when lockout starts and ends. They do not apply or remove the servicing locks." },
  { id: "lo-04", category: "loto", topic: "Verify", q: "After applying lockout devices, the authorized employee must:", choices: ["Assume the energy is gone", "Verify isolation — try to start the machine and/or test for residual energy", "Leave the area immediately", "Remove guards only"], a: 1, why: "Verification (try-out) catches wrong breakers, dual feeds, and stored energy. Return controls to off after the test." },
  { id: "lo-05", category: "loto", topic: "Personal lock", q: "Each authorized employee working on a machine generally must:", choices: ["Share one lock for the crew", "Apply their own lock (or equivalent personal control in a group lockout)", "Use a tag only, always", "Leave the key in the lock"], a: 1, why: "One person, one lock, one key is the core idea. Group lockout uses a lockbox or hasp so each person still has personal protection." },
  { id: "lo-06", category: "loto", topic: "Group", q: "In a group lockout, the last lock removed should be:", choices: ["Anyone’s", "The lock of the person who verifies the machine is clear of workers and ready to re-energize, after each worker has removed their personal lock", "Left on forever", "The supervisor’s lock removed first so production can start"], a: 1, why: "Primary/crew lock stays until the job is clear. Nobody is exposed when energy is restored." },
  { id: "lo-07", category: "loto", topic: "Stored energy", q: "Hazardous energy includes stored energy such as:", choices: ["Only electricity", "Capacitors, springs, raised parts (gravity), hydraulic pressure, and residual process chemicals", "Only steam", "Sunshine"], a: 1, why: "Relieve, disconnect, restrain, or otherwise make stored energy safe. A locked breaker is not enough if a ram can drop." },
  { id: "lo-08", category: "loto", topic: "Cord and plug", q: "Cord-and-plug equipment is generally exempt from full LOTO if:", choices: ["It is unplugged and under the exclusive control of the employee performing the work", "It is over 50 volts", "It has a red cord", "Two people are working on it"], a: 0, why: "1910.147(a)(2)(iii)(A): unplug it and keep the plug in your control. If you walk away, lockout or another worker can plug it in." },
  { id: "lo-09", category: "loto", topic: "Annual", q: "Lockout/tagout procedures must be inspected at least:", choices: ["Monthly", "Annually", "Every 5 years", "Never if no injuries occurred"], a: 1, why: "1910.147(c)(6): periodic inspection at least annually, including a review with authorized employees." },
  { id: "lo-10", category: "loto", topic: "Someone else’s lock", q: "You may remove another person’s lock only:", choices: ["Whenever you need the machine", "When the employer follows a documented emergency-removal procedure after verifying the person is not at the machine", "If you are a supervisor", "If the lock is red"], a: 1, why: "1910.147(e)(3): specific steps, including checking that the employee is not in the facility. Never cut a lock casually." },

  { id: "mh-01", category: "materials", topic: "Suspended load", q: "Employees should not:", choices: ["Use tag lines on loads that may spin", "Work under a suspended load", "Stay out of the swing radius", "Watch a lift from a safe location"], a: 1, why: "1926.1425 / 1910.180: never stand under a hoisted load. Rigging fails." },
  { id: "mh-02", category: "materials", topic: "Tag line", q: "A tag line is used to:", choices: ["Measure trench depth", "Control a suspended load from the side so it does not spin or strike people or objects", "Replace a sling", "Lock out a crane"], a: 1, why: "Keep hands off the load. Guide it with a rope from outside the fall/swing zone." },
  { id: "mh-03", category: "materials", topic: "Crane operator", q: "Construction crane operators must generally be:", choices: ["Qualified/certified as required by 1926 Subpart CC", "Any laborer with a Class C license", "OSHA 10 card holders only", "Self-taught on the job the same day"], a: 0, why: "Subpart CC requires qualified operators. Certification/qualification rules apply by crane type and capacity." },
  { id: "mh-04", category: "materials", topic: "Load chart", q: "A crane’s load chart:", choices: ["Is a suggestion", "Must be followed; capacity changes with boom length, angle, and configuration", "Applies only to the truck’s GVWR", "Can be exceeded by 10%"], a: 1, why: "Exceeding the chart causes tip-overs and boom failures. Know radius, reeving, and deductions." },
  { id: "mh-05", category: "materials", topic: "Outriggers", q: "When a crane is equipped with outriggers, they must be:", choices: ["Used according to the manufacturer and load chart — often fully extended with floats on firm surfaces", "Extended only on one side", "Optional if the ground looks hard", "Retracted to save space on every lift"], a: 0, why: "Improper setup is a leading crane killer. Cribbing, underground voids, and partial extension change capacity." },
  { id: "mh-06", category: "materials", topic: "Swing radius", q: "The rear swing radius of a rotating superstructure must be:", choices: ["Painted but left open", "Barricaded to prevent workers from being crushed", "Used as a break area", "Ignored on crawler cranes"], a: 1, why: "1926.1424: prevent entry into the swing radius. Counterweights crush people against objects." },
  { id: "mh-07", category: "materials", topic: "Forklift training", q: "Powered industrial truck operators must be:", choices: ["Trained, evaluated, and certified by the employer before operating", "Licensed by OSHA directly", "Over 21 only", "Trained only if the forklift can lift more than 10,000 pounds"], a: 0, why: "1910.178(l): formal instruction, practical training, and evaluation. Refresher after incidents or every 3 years evaluation." },
  { id: "mh-08", category: "materials", topic: "Forklift inspect", q: "Forklifts must be examined:", choices: ["Yearly", "At least daily, and after each shift when used around the clock", "Only when they break", "Never if new"], a: 1, why: "1910.178(q)(7): daily exam. Remove from service if defects affect safety." },
  { id: "mh-09", category: "materials", topic: "Ring test", q: "Before mounting an abrasive wheel, a ring test:", choices: ["Checks for cracks — a clear ring vs a dull thud", "Measures RPM only", "Is optional", "Applies only to diamond blades"], a: 0, why: "1910.215: tap the wheel. A cracked wheel can explode. Also check RPM rating vs machine speed." },
  { id: "mh-10", category: "materials", topic: "Work rest", q: "On a bench grinder, the work rest should be adjusted to within:", choices: ["1/2 inch of the wheel", "1/8 inch of the wheel", "1 inch of the wheel", "3 inches of the wheel"], a: 1, why: "1910.215(a)(4): work rest max 1/8 inch. Tongue guard (spark arrestor) max 1/4 inch. Prevents the workpiece from jamming." },
  { id: "mh-11", category: "materials", topic: "Powder-actuated", q: "Powder-actuated tools may be operated only by:", choices: ["Anyone on the crew", "Employees who have been trained", "OSHA inspectors", "Minors under 16"], a: 1, why: "1926.302(e): trained operators, unloaded when not in use, never fire into hard or brittle materials that can spall." },
  { id: "mh-12", category: "materials", topic: "Cylinders", q: "Compressed gas cylinders in storage should be:", choices: ["On their side with caps off", "Upright, secured, and capped when regulators are off", "In the sun next to oil rags", "Stacked like firewood"], a: 1, why: "1926.350 / 1910.101: secure upright, valve protection caps, protect from heat and damage." },
  { id: "mh-13", category: "materials", topic: "Oxygen-fuel", q: "Oxygen cylinders in storage must be separated from fuel-gas cylinders by:", choices: ["6 inches", "A minimum 20-foot distance, or a 5-foot-high fire wall with a 30-minute rating", "No separation if capped", "One pallet width"], a: 1, why: "1926.350(a)(10): 20 feet or a 5-foot 30-minute barrier. Keep oils away from oxygen." },
  { id: "mh-14", category: "materials", topic: "Rigging", q: "Slings and rigging hardware must be:", choices: ["Inspected each day before use and as needed during use; damaged gear removed", "Used until they break", "Knotted to shorten a synthetic sling", "Shock-loaded to test capacity"], a: 0, why: "1926.251 / 1910.184: inspect, never exceed capacity, no knots in synthetic slings, protect from sharp edges." },
  { id: "mh-15", category: "materials", topic: "Capacity", q: "A forklift’s rated capacity:", choices: ["Applies at the specified load center; a longer or higher load can reduce capacity", "Never changes with load position", "Can be ignored with the seat belt on", "Doubles when you drive faster"], a: 0, why: "The data plate assumes a load center (often 24 inches). A long load or raised mast reduces capacity and stability." },

  { id: "hh-01", category: "health", topic: "Silica PEL", q: "OSHA’s 8-hour TWA PEL for respirable crystalline silica is:", choices: ["10 μg/m³", "25 μg/m³", "50 μg/m³", "250 μg/m³"], a: 2, why: "1926.1153 / 1910.1053: 50 μg/m³ PEL. Action level is 25 μg/m³." },
  { id: "hh-02", category: "health", topic: "Table 1", q: "Construction silica Table 1 allows employers to:", choices: ["Ignore silica if they wet-cut without checking the table", "Follow specified exposure-control methods for listed tasks instead of exposure monitoring in many cases", "Use dry sweeping as the primary control", "Skip respirators whenever a fan is on"], a: 1, why: "If you fully implement Table 1 (water, dust collection, shrouds, and listed respirators), you may not need to measure silica for that task." },
  { id: "hh-03", category: "health", topic: "Lead", q: "The construction lead PEL is an 8-hour TWA of:", choices: ["10 μg/m³", "30 μg/m³", "50 μg/m³", "500 μg/m³"], a: 2, why: "1926.62: 50 μg/m³ PEL, 30 μg/m³ action level. Demolition, welding on painted steel, and blasting are high-risk." },
  { id: "hh-04", category: "health", topic: "Asbestos", q: "If you encounter suspected asbestos-containing material:", choices: ["Break it up quickly to finish the job", "Do not disturb it; stop and follow asbestos rules with a competent person", "Wet it with gasoline", "Bag it with household trash"], a: 1, why: "1926.1101: Class I–IV work, competent person, wetting, negative pressure, and training. Disturbing ACM without controls spreads fibers." },
  { id: "hh-05", category: "health", topic: "CO", q: "Carbon monoxide is dangerous because it is:", choices: ["Green and smells like almonds", "Colorless, odorless, and binds to hemoglobin so you cannot carry oxygen", "Only a problem outdoors", "Heavier than air always, so it stays on the floor"], a: 1, why: "Generators, heaters, and forklifts in poorly ventilated areas kill people. Use CO alarms and ventilation; never run engines in closed spaces." },
  { id: "hh-06", category: "health", topic: "Heat", q: "A basic heat-illness prevention approach is:", choices: ["Work through dizziness to acclimate faster", "Water, rest, shade, and gradual acclimatization", "Salt tablets only, no water", "Dark non-breathable clothing"], a: 1, why: "OSHA uses the General Duty Clause and a National Emphasis Program on heat. New workers are at highest risk in the first days." },
  { id: "hh-07", category: "health", topic: "Acclimatization", q: "Heat acclimatization means:", choices: ["Skipping water after week one", "Gradually increasing work time in the heat over about 1–2 weeks so the body adapts", "Working nights only forever", "Taking a cold shower once"], a: 1, why: "Most heat deaths occur in the first few days. Supervisors should reduce load and watch new and returning workers." },
  { id: "hh-08", category: "health", topic: "Noise", q: "Hearing protection is required when exposures exceed the PEL, and a conservation program is generally triggered at:", choices: ["The action level of 85 dBA TWA in general industry", "70 dBA", "Only 140 dBA", "Any conversation-level noise"], a: 0, why: "1910.95: 85 dBA action level starts monitoring, audiograms, training, and offering protection." },
  { id: "hh-09", category: "health", topic: "Cold", q: "Hypothermia can occur when:", choices: ["Only at temperatures below 0°F", "The body loses heat faster than it produces it — even in cool, wet, windy conditions above freezing", "You drink water", "You wear a hard hat"], a: 1, why: "Wet clothing and wind strip heat. Watch for shivering, confusion, and slurred speech. Get the person warm and dry." },
  { id: "hh-10", category: "health", topic: "Hex chrome", q: "Hexavalent chromium exposures are a concern primarily during:", choices: ["Office work", "Welding, cutting, or grinding stainless steel or chromate paints", "Using wood saws on pine", "Indoor painting with latex only"], a: 1, why: "1910.1026 / 1926.1126: hex chrome from stainless welding fume and some paints. Ventilate and use the right respirator." },
  { id: "hh-11", category: "health", topic: "Bloodborne", q: "The Bloodborne Pathogens Standard applies to:", choices: ["Occupational exposure to blood or other potentially infectious materials", "Only hospitals in New York", "Construction dust only", "Food service exclusively"], a: 0, why: "1910.1030: exposure control plan, HBV vaccine, PPE, and training. Construction first-aid providers can be covered." },
  { id: "hh-12", category: "health", topic: "Welding", q: "Welding and cutting in confined or poorly ventilated areas require:", choices: ["No extra controls", "Adequate ventilation and/or respirators; watch for metals, ozone, and asphyxiation", "Only a darker lens", "Pure oxygen to “clear the air”"], a: 1, why: "1926 Subpart J / 1910.252: ventilate. Never use oxygen to blow out a space. Check for coatings (lead, cadmium, chrome)." },
  { id: "hh-13", category: "health", topic: "Solvents", q: "Organic solvents can cause:", choices: ["Only skin dryness, never systemic effects", "Dizziness, narcosis, liver/kidney effects, and fire hazards depending on the chemical", "Better lung function", "No need for SDS review"], a: 1, why: "Use ventilation, gloves rated for the solvent, and explosion-safe practices. Read the SDS." },

  { id: "fr-01", category: "fire", topic: "Class A", q: "A Class A fire involves:", choices: ["Flammable liquids", "Ordinary combustibles such as wood, paper, and cloth", "Energized electrical equipment", "Combustible metals"], a: 1, why: "A = ash (ordinary combustibles). Water and ABC dry chemical work on many Class A fires." },
  { id: "fr-02", category: "fire", topic: "Class B", q: "A Class B fire involves:", choices: ["Wood", "Flammable liquids and gases such as gasoline, oil, and propane", "Magnesium", "Cooking oil in a deep fryer only (Class K)"], a: 1, why: "B = barrel (liquids). Do not use a water hose stream as the primary agent on burning fuel." },
  { id: "fr-03", category: "fire", topic: "Class C", q: "A Class C fire involves:", choices: ["Energized electrical equipment", "Paper only", "Flammable metals only", "Grease in a kitchen vat only"], a: 0, why: "C = current. De-energize if you can. Use a non-conductive extinguisher. After power is off, it may become Class A or B." },
  { id: "fr-04", category: "fire", topic: "PASS", q: "PASS for a portable extinguisher means:", choices: ["Pull, Aim, Squeeze, Sweep", "Push, Alert, Stop, Sprint", "Point, Advance, Spray, Stop", "Pull alarm, Assemble, Stay, Shelter"], a: 0, why: "Pull the pin, aim at the base, squeeze, sweep side to side. Fight only a small fire with a clear escape path." },
  { id: "fr-05", category: "fire", topic: "Exit width", q: "An exit route must be at least how wide at all points?", choices: ["18 inches", "22 inches", "28 inches", "48 inches always, with no exceptions"], a: 2, why: "1910.36(g)(2): minimum 28 inches. Occupant load can require more. Keep it unobstructed." },
  { id: "fr-06", category: "fire", topic: "Locked exits", q: "Exit doors that must be used during an emergency:", choices: ["May be chained during business hours to prevent theft", "Must be unlocked from the inside without keys, tools, or special knowledge", "Can be blocked by pallets if labeled", "Are optional in warehouses"], a: 1, why: "1910.36(d): panic hardware or simple operation. Locked/blocked exits are a frequent citation and a killer in fires." },
  { id: "fr-07", category: "fire", topic: "EAP", q: "An Emergency Action Plan generally includes:", choices: ["Only a phone list for payroll", "Evacuation procedures, alarm system, assembly areas, and roles such as who stays to shut down critical ops", "Only a map of the parking lot", "Nothing written if you have fewer than 500 employees always"], a: 1, why: "1910.38: written EAP if you have more than 10 employees. Train everyone. Construction uses 1926.35." },
  { id: "fr-08", category: "fire", topic: "Travel distance A", q: "Maximum travel distance to a Class A extinguisher is generally:", choices: ["25 feet", "50 feet", "75 feet", "200 feet"], a: 2, why: "1910.157(d)(2): 75 feet for Class A. Class B is 50 feet." },
  { id: "fr-09", category: "fire", topic: "Monthly check", q: "Portable fire extinguishers must be visually inspected:", choices: ["Once a decade", "Monthly", "Only after use", "Never if tagged"], a: 1, why: "1910.157(e): monthly visual inspection plus annual maintenance. Check pressure, pin, and access." },
  { id: "fr-10", category: "fire", topic: "Hot work", q: "Hot work (welding, cutting, grinding that can start fires) should include:", choices: ["No precautions if you have a fire watch “in mind”", "Removing or protecting combustibles, a fire watch when required, and extinguishers", "Only working faster", "Using oxygen to blow dust"], a: 1, why: "1910.252 / 1926 Subpart J: fire watch at least 30 minutes after hot work in many cases. Permits are a common employer control." },

  { id: "ww-01", category: "walking", topic: "Housekeeping", q: "Housekeeping on walking-working surfaces means:", choices: ["A monthly deep clean only", "Keeping floors clean, dry so far as possible, and clear of clutter that causes slips, trips, and falls", "Storing lumber in aisles to save time", "Leaving scrap until demob"], a: 1, why: "1910.22 / 1926.25: regular housekeeping. Construction debris is a leading trip source." },
  { id: "ww-02", category: "walking", topic: "Aisles", q: "Aisles and passageways must be:", choices: ["Kept clear and in good repair", "Used for extra pallet storage", "Blocked during inventory", "Optional in warehouses"], a: 0, why: "1910.22(d) / 1926.25: maintain access. Mark permanent aisles where required." },
  { id: "ww-03", category: "walking", topic: "Cords", q: "Cords and hoses across walkways:", choices: ["Are the best way to protect them", "Create trip hazards and should be routed, covered, or suspended", "Are required by OSHA", "Only matter on stairs"], a: 1, why: "Elevate, cover with a cord protector, or reroute. Do not create a new trip to avoid a slightly longer cord run." },
  { id: "ww-04", category: "walking", topic: "Holes", q: "Floor holes must be:", choices: ["Left open so they are obvious", "Guarded or covered", "Marked with chalk only", "Allowed if smaller than a boot"], a: 1, why: "1910.28 / 1926.501: protect holes. Covers must be secured and marked. People fall through skylights and unguarded openings." },
  { id: "ww-05", category: "walking", topic: "Stairs", q: "Stairways with four or more risers (or rising more than 30 inches) generally need:", choices: ["No rails if used by construction crews", "Stair rail systems / handrails as required", "A ladder instead", "A warning line only"], a: 1, why: "1910.25 / 1926.1052: handrails and stair rails. Uniform riser height matters too." },
  { id: "ww-06", category: "walking", topic: "Weather", q: "Ice, mud, and wet floors should be:", choices: ["Ignored until someone falls", "Cleaned, treated, or marked, and workers given traction footwear when needed", "Covered with cardboard as a permanent solution", "Used to slow forklifts naturally"], a: 1, why: "Slips are preventable. Salt/sand ice, squeegee water, and use mats. Cardboard hides hazards and gets slick." },
  { id: "ww-07", category: "walking", topic: "Exits clear", q: "Materials may not be stored in a way that:", choices: ["Blocks exits, fire equipment, or access to electrical panels", "Is neat", "Uses racks", "Is labeled"], a: 0, why: "Keep egress and emergency equipment reachable. 1910.37 and housekeeping rules overlap here." }
];
